import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new Group();
  const disposables = [];
  const timelines = [];
  const primitiveResults = [];
  let disposed = false;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const makeGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    material.colorNode = mix(
      vec3(0.043, 0.043, 0.063),
      mix(
        vec3(0.086, 0.086, 0.114),
        vec3(0.043, 0.043, 0.059),
        smoothstep(0.42, 0.92, uv().y)
      ),
      smoothstep(0.0, 1.0, uv().y)
    );
    disposables.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeometry, makeGradientMaterial());
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeometry);

  const surfaceGeometry = new PlaneGeometry(5.8, 3.625);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: colors.surface
  });
  surfaceMaterial.transparent = true;
  surfaceMaterial.opacity = 0.72;
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.set(0, 0, -1.55);
  root.add(surface);
  disposables.push(surfaceGeometry, surfaceMaterial);

  const accentGeometry = new PlaneGeometry(2.15, 0.018);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  accentMaterial.transparent = true;
  accentMaterial.opacity = 0.92;
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.42, -0.82, -0.15);
  root.add(accent);
  disposables.push(accentGeometry, accentMaterial);

  const spriteGeometry = new PlaneGeometry(3.2, 2);
  const spriteMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    depthWrite: false
  });
  const sprite = new Mesh(spriteGeometry, spriteMaterial);
  sprite.position.set(0, 0, -0.45);
  root.add(sprite);
  disposables.push(spriteGeometry, spriteMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0;
  for (const item of items) {
    const text = typeof item.text === 'string' ? item.text : '';
    if (!text) continue;

    const label = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1
    });

    label.position.set(-1.42, 0.02 - textOffset, 0.12);
    root.add(label);
    textOffset += 0.42;
  }

  const textureUrl = config.imageUrl;
  if (textureUrl) {
    ctx.textureLoader.loadTexture(textureUrl).then((texture) => {
      if (disposed || !texture) return;

      const atlasTexture = texture.clone();
      const image = atlasTexture.image;
      const width = image?.width || 512;
      const height = image?.height || 320;
      const region = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      atlasTexture.wrapS = THREE.ClampToEdgeWrapping;
      atlasTexture.wrapT = THREE.ClampToEdgeWrapping;
      atlasTexture.repeat.set(region.width / width, region.height / height);
      atlasTexture.offset.set(
        region.x / width,
        1 - (region.y + region.height) / height
      );
      atlasTexture.needsUpdate = true;

      spriteMaterial.map = atlasTexture;
      spriteMaterial.needsUpdate = true;
      disposables.push(atlasTexture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    surface.position,
    { y: -0.2, opacity: 0.55 },
    { y: 0, opacity: 0.72, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    sprite.position,
    { y: -0.22 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    '<'
  );
  entrance.fromTo(
    accent.scale,
    { x: 0.2 },
    { x: 1, duration: 0.9, ease: 'power4.out' },
    '-=0.45'
  );
  timelines.push(entrance);

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) root.quaternion.copy(camera.quaternion);
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const timeline of timelines) timeline.kill();

    root.traverse((object) => {
      object.onBeforeRender = null;
    });

    for (const resource of disposables) {
      resource?.dispose?.();
    }

    root.clear();
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  return root;
}

export default createNode;
